":"teacher","skill":"gentle fitness"},{"activity":"badminton","role":"partner","skill":null},{"activity":"jogging","role":"partner","skill":null},{"activity":"gardening","role":"learner","skill":null}],"availability":[{"day":2,"start":"18:00","end":"21:00"},{"day":4,"start":"18:00","end":"21:00"},{"day":6,"start":"09:00","end":"12:00"},{"day":7,"start":"09:00","end":"12:00"}],"is_demo":true},{"id":"11111111-1111-4111-8111-000000000010","name":"Nur Aisyah","age_range":"30s","participant_group":"young-adult","block":"49","languages":["english","malay"],"bio":"I enjoy photographing everyday moments around Pek Kio. I can show you how to take a lovely phone photo, and would be delighted to learn a family recipe.","intents":[{"activity":"photography","role":"teacher","skill":"phone photography"},{"activity":"cooking","role":"learner","skill":"Hokkien cooking"},{"activity":"language","role":"learner","skill":"Mandarin conversation"},{"activity":"chess","role":"teacher","skill":"beginner chess"}],"availability":[{"day":2,"start":"18:00","end":"21:00"},{"day":4,"start":"18:00","end":"21:00"},{"day":6,"start":"09:00","end":"12:00"},{"day":7,"start":"09:00","end":"12:00"}],"is_demo":true},{"id":"11111111-1111-4111-8111-000000000011","name":"Jason & Wei Ling","age_range":"Parents in their 40s","participant_group":"family","block":"41","languages":["english","mandarin"],"bio":"Our eight-year-old asks how every leaf grows. We would love to garden with an experienced neighbour and learn chess together as a family.","intents":[{"activity":"gardening","role":"learner","skill":"herbs and container gardening"},{"activity":"chess","role":"learner","skill":"beginner chess"},{"activity":"cooking","role":"learner","skill":"Hokkien cooking"}],"availability":[{"day":6,"start":"09:00","end":"12:00"},{"day":7,"start":"09:00","end":"12:00"}],"is_demo":true},{"id":"11111111-1111-4111-8111-000000000012","name":"Siti & Farid","age_range":"Parents in their 30s","participant_group":"family","block"